/bin/zsh -c "git merge --ff-only origin/main && mv migrations/002_refunds.sql migrations/003_refunds.sql && cat > src/factory.ts <<'EOF'
import { OrdersDb } from './db';
import { RefundRepo } from './refund-repo';

export function refundOrder(client: OrdersDb) {
  const repo = new RefundRepo(client);
  repo.save();
}
EOF
cat > order-tags.sql <<'EOF'
CREATE TABLE order_tag (
  order_tag_id TEXT PRIMARY KEY,
  order_id TEXT NOT NULL,
  tag_id TEXT NOT NULL,
  UNIQUE (order_id, tag_id)
);
EOF
cat > test/refund.test.ts <<'EOF'
import { test, expect } from 'bun:test';
import { OrdersDb } from '../src/db';
import { refundOrder } from '../src/factory';
import { RefundRepo } from '../src/refund-repo';

test('refund repository writes through the injected client', () => {
  const client = new OrdersDb('synthetic://db');
  const repo = new RefundRepo(client);
  repo.save();
  expect(client.writes.length).toBe(1);
  expect(client.writes[0]).toBe('refund');
});

test('refundOrder writes through the supplied client', () => {
  const client = new OrdersDb('synthetic://db');
  refundOrder(client);
  expect(client.writes.length).toBe(1);
  expect(client.writes[0]).toBe('refund');
});
EOF
bash gate.sh"

